// Included inside Processor. Capture XML and immutable sources under the same short lock.
bool portableBackground526=true;
std::shared_ptr<PortableMedia526::Project> portableProject526=std::make_shared<PortableMedia526::Project>();
static void requestPortableTree526(std::shared_ptr<const AudioData> data,int depth=0){if(!data||depth>4)return;PortableMedia526::request(data);for(auto& r:data->sfzRegions)if(r.source!=data)requestPortableTree526(r.source,depth+1);}
bool usesEmbedded526(int depth=0){const juce::ScopedLock guard(lock);if(audio&&audio->embedded526)return true;if(multiMap)for(auto& r:*multiMap)if(r.source&&r.source->embedded526)return true;return depth<4&&extractionInstrument&&extractionInstrument.get()!=this&&extractionInstrument->usesEmbedded526(depth+1);}
void preparePortable526(){if(!portableProject526->enabled)return;std::vector<std::shared_ptr<const AudioData>> sources;std::shared_ptr<Processor> instrument;{const juce::ScopedTryLock g(lock);if(!g.isLocked())return;if(audio)sources.push_back(audio);if(multiMap)for(auto& r:*multiMap)if(r.source)sources.push_back(r.source);instrument=extractionInstrument;}for(auto& a:sources)requestPortableTree526(a);if(instrument&&instrument.get()!=this)instrument->preparePortable526();}
std::unique_ptr<juce::XmlElement> capturePortable526(std::vector<PortableMedia526::Source>& sources,std::map<const AudioData*,juce::String>& ids,int depth=0){const juce::ScopedLock guard(lock);auto xml=configurationXml(true);auto bind=[&](std::shared_ptr<const AudioData> a){if(!a)return juce::String();auto found=ids.find(a.get());if(found!=ids.end())return found->second;auto path=juce::File("/SliceGroupsEmbedded").getChildFile(juce::String(ids.size())).getChildFile(juce::File(a->path).getFileName()).getFullPathName();ids[a.get()]=path;sources.push_back({a,path});return path;};if(audio)xml->setAttribute("file",bind(audio));if(auto* map=xml->getChildByName("multiMap")){auto rows=shotRegions();int i=0;for(auto* r:map->getChildIterator()){if(i<(int)rows.size())r->setAttribute("source",bind(rows[i].source));++i;}}
 if(extractionInstrument&&extractionInstrument.get()!=this&&depth<4){xml->deleteAllChildElementsWithTagName("extractionInstrument");auto patch=extractionInstrument->capturePortable526(sources,ids,depth+1);auto* child=xml->createNewChildElement("extractionInstrument");child->addChildElement(patch.release());}else if(xml->getChildByName("extractionInstrument"))xml->setAttribute("embeddingError526","Confirmed audition audio is unavailable; select the audition sound again before saving a portable Set");return xml;}
void prepareConfirmedPortable526(){if(extractionInstrument||extractionInstrumentXml.isEmpty())return;static thread_local int depth=0;if(depth>=4)return;auto xml=juce::parseXML(extractionInstrumentXml);if(!xml)return;struct Count{int& v;Count(int& n):v(n){++v;}~Count(){--v;}}count(depth);auto instrument=std::make_shared<Processor>(false);instrument->autoSave=false;instrument->trackOffline=true;auto source=instrument->readAudioForConfiguration(juce::File(xml->getStringAttribute("file")),*xml);if(!source)return;instrument->audio=source;if(!instrument->applyConfiguration(*xml,true))return;instrument->sequenceEnabled=false;instrument->playMode=false;instrument->outputRate=outputRate;extractionInstrument=std::move(instrument);}
void writePortable526(juce::XmlElement& xml,const std::vector<PortableMedia526::Source>& sources,juce::MemoryBlock& output,bool embed){xml.setAttribute("embedSamplesInSet526",embed);xml.setAttribute("mediaOrigin526",portableProject526->owner);if(!embed){copyXmlToBinary(xml,output);return;}juce::String error=xml.getStringAttribute("embeddingError526");std::function<void(const juce::XmlElement&)> validate=[&](const juce::XmlElement& node){if(node.hasAttribute("embeddingError526"))error=node.getStringAttribute("embeddingError526");for(auto* child:node.getChildIterator())validate(*child);};validate(xml);if(error.isEmpty()&&PortableMedia526::encode(xml,sources,output,error)){portableProject526->fail({});return;}
 std::map<juce::String,juce::String> originals;for(auto& s:sources)originals[s.path]=s.audio->path;PortableMedia526::rewrite(xml,originals);xml.setAttribute("embeddingError526",error);copyXmlToBinary(xml,output);portableProject526->fail("Set audio is not fully embedded: "+error);}
